script:
frappe.ui.form.on('Opportunity', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Create Job Opening'), function() {
                frappe.new_doc('Job Opening', {
                custom_opportunity: frm.doc.name  // or use frm.doc.name if that's the Lead ID
                });
            });
        }
    }
});
